import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updatePostHandler } from "../handlers/updatePostHandler";
import type { ApiError } from "../runtime/client";
import type { FeedPartition } from "../types/FeedPartition";
import type { UpdatePostRequest } from "../types/UpdatePostRequest";

type Data = Awaited<ReturnType<typeof updatePostHandler>>;
type Vars = { postId: FeedPartition; req: UpdatePostRequest };

export function useUpdatePost(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updatePostHandler(vars.postId, vars.req),
    ...options,
  });
}
